def gen(rng):
    def build(n, shape):
        # returns (level-order token string, list of values)
        vals = rng.sample(range(1, 100001), n)
        left = [-1] * n
        right = [-1] * n
        if shape == 'chainL':
            for i in range(n - 1):
                left[i] = i + 1
        elif shape == 'chainR':
            for i in range(n - 1):
                right[i] = i + 1
        elif shape == 'zigzag':
            for i in range(n - 1):
                if i % 2 == 0:
                    left[i] = i + 1
                else:
                    right[i] = i + 1
        elif shape == 'complete':
            for i in range(n):
                if 2 * i + 1 < n:
                    left[i] = 2 * i + 1
                if 2 * i + 2 < n:
                    right[i] = 2 * i + 2
        else:
            free = [(0, 0), (0, 1)]
            for i in range(1, n):
                k = rng.randrange(len(free))
                free[k], free[-1] = free[-1], free[k]
                p, side = free.pop()
                if side == 0:
                    left[p] = i
                else:
                    right[p] = i
                free.append((i, 0))
                free.append((i, 1))
        toks = [str(vals[0])]
        order = [0]
        qi = 0
        while qi < len(order):
            u = order[qi]
            qi += 1
            for c in (left[u], right[u]):
                if c == -1:
                    toks.append('null')
                else:
                    toks.append(str(vals[c]))
                    order.append(c)
        while toks[-1] == 'null':
            toks.pop()
        return toks, vals
    def make(n, shape, pick=None):
        toks, vals = build(n, shape)
        s = vals[rng.randrange(n)] if pick is None else vals[pick]
        return ' '.join(toks) + '\n' + str(s)
    tests = ['7\n7', '1 2\n1', '1 2\n2', '1 null 2\n1', '1 2 3 4 5 null 6\n2', '1 2 3 4 5 null 6\n6',
             '1 2 null 3 null 4\n3', '1 2 null 3 null 4\n4']
    for _ in range(40):
        n = rng.randint(1, 12)
        tests.append(make(n, rng.choice(['rand', 'rand', 'chainL', 'chainR', 'zigzag', 'complete'])))
    N = 50000
    tests.append(make(N, 'rand'))
    tests.append(make(N, 'chainL', 0))
    tests.append(make(N, 'zigzag', N // 2))
    tests.append(make(N, 'complete'))
    tests.append(make(N, 'chainR', N - 1))
    return tests
